### Script: Crypto-Miner Hidden in Browser

```javascript
// This script runs once when loaded into your browser
// It attempts to detect if a mining script is running on your system
// If detected, it will attempt to disable it and clean up traces

// Step 1: Check for existing miners
const minerList = ['Cuckoo', 'Avalon', 'T-Rex'];
for (let i = 0; i < minerList.length; i++) {
  if (typeof(performance.getEntriesByName('CryptoHijack')[0]) === 'object' &&
    minerList[i] === performance.getEntriesByName('CryptoHijack')[0].name) {
    // Found running miner - let us disable it
    console.log('Miner found:', minerList[i]);
    // Remove this miner
    const miner = document.querySelector('.miner');
    if (miner) {
      miner.remove();
    }
  }
}

// Step 2: Check for 'hijack' detection
const hijackScript = 'CryptoHijack';
if (document.querySelector(hijackScript)) {
  console.log(hijackScript + ' is running');
  // Create a hidden div to detect if the miner is actually running
  let hiddenDiv = document.createElement('div');
  hiddenDiv.style.display = 'none';
  hiddenDiv.className = 'hijack-detection';
  document.body.appendChild(hiddenDiv);

  // Hook into events so you can see when the script loads
  // The script that runs is the one that creates this div
  // We need to check if it exists before we act
  const createHiddenDiv = () => {
    if (hiddenDiv.style.display === 'none') {
      console.log('Miner detected - disabling...');
      // Remove the miner (or your main script)
      const miner = document.querySelector('.miner');
      if (miner) {
        miner.remove();
      }
    }
  };

  // Hook into the event listener
  document.addEventListener('DOMContentLoaded', createHiddenDiv);
  // ... add other event listeners for window load/navigation...
}
```

